#include <Arduino.h>
#include <LittleFS.h>
#include "esp_sleep.h"

const int LDR_PIN = 3;
const int BUTTON_PIN = 4;

const uint32_t LOG_INTERVAL_SECONDS = 120;

RTC_DATA_ATTR bool loggingActive = false;
RTC_DATA_ATTR uint32_t readingNumber = 0;

void takeReading();
void startLogging();
void stopLogging();
void showStatus();
void downloadLog();
void clearLog();
void handleSerial();

void setup() {
  Serial.begin(115200);
  delay(500);

  pinMode(BUTTON_PIN, INPUT_PULLUP);

  analogReadResolution(12);
  analogSetPinAttenuation(LDR_PIN, ADC_11db);

  if (!LittleFS.begin(true)) {
    Serial.println("LittleFS error");
  }

  Serial.println();
  Serial.println("ESP32-C3 LIGHT LOGGER");
  Serial.println("Ready.");
  Serial.println("Commands: START STOP STATUS DOWNLOAD CLEAR HELP");
}

void loop() {

  // Check serial commands
  handleSerial();

  // Check push button
  if (digitalRead(BUTTON_PIN) == LOW) {

    delay(50);

    if (digitalRead(BUTTON_PIN) == LOW) {

      if (loggingActive) {
        stopLogging();
      } else {
        startLogging();
      }

      while (digitalRead(BUTTON_PIN) == LOW) {
        delay(10);
      }
    }
  }

  delay(20);
}

void handleSerial() {

  if (!Serial.available()) {
    return;
  }

  String command = Serial.readStringUntil('\n');
  command.trim();
  command.toUpperCase();

  if (command == "START") {
    startLogging();
  }

  else if (command == "STOP") {
    stopLogging();
  }

  else if (command == "STATUS") {
    showStatus();
  }

  else if (command == "DOWNLOAD") {
    downloadLog();
  }

  else if (command == "CLEAR") {
    clearLog();
  }

  else if (command == "HELP") {
    Serial.println();
    Serial.println("Commands:");
    Serial.println("START    - start logging");
    Serial.println("STOP     - stop logging");
    Serial.println("STATUS   - show logger status");
    Serial.println("DOWNLOAD - print CSV data");
    Serial.println("CLEAR    - erase CSV data");
    Serial.println("HELP     - show commands");
    Serial.println();
  }

  else {
    Serial.println("Unknown command. Type HELP.");
  }
}

void startLogging() {

  loggingActive = true;

  Serial.println();
  Serial.println("Logging: ON");

  takeReading();

  Serial.println("Sleeping for 2 minutes...");

  Serial.flush();

  esp_sleep_enable_timer_wakeup(
    (uint64_t)LOG_INTERVAL_SECONDS * 1000000ULL
  );

  esp_deep_sleep_start();
}

void stopLogging() {

  loggingActive = false;

  Serial.println();
  Serial.println("Logging: OFF");
}

void showStatus() {

  Serial.println();
  Serial.println("----- STATUS -----");

  Serial.print("Logging: ");
  Serial.println(loggingActive ? "ON" : "OFF");

  Serial.print("Readings: ");
  Serial.println(readingNumber);

  if (LittleFS.exists("/lightlog.csv")) {

    File file = LittleFS.open("/lightlog.csv", FILE_READ);

    if (file) {
      Serial.print("Log size: ");
      Serial.print(file.size());
      Serial.println(" bytes");
      file.close();
    }

  } else {
    Serial.println("Log file: none");
  }

  Serial.println("------------------");
}

void downloadLog() {

  Serial.println();
  Serial.println("----- CSV DATA -----");

  File file = LittleFS.open("/lightlog.csv", FILE_READ);

  if (!file) {
    Serial.println("No log file found.");
    Serial.println("--------------------");
    return;
  }

  while (file.available()) {
    Serial.write(file.read());
  }

  file.close();

  Serial.println();
  Serial.println("----- END CSV -----");
}

void clearLog() {

  if (LittleFS.exists("/lightlog.csv")) {
    LittleFS.remove("/lightlog.csv");
  }

  readingNumber = 0;

  Serial.println();
  Serial.println("Log cleared.");
}

void takeReading() {

  int adcValue = analogRead(LDR_PIN);

  float voltage = (adcValue / 4095.0) * 3.3;

  readingNumber++;

  File file = LittleFS.open("/lightlog.csv", FILE_APPEND);

  if (!file) {
    Serial.println("ERROR: Could not open log file.");
    return;
  }

  if (readingNumber == 1) {
    file.println("Reading,Elapsed_seconds,ADC,Voltage");
  }

  uint32_t elapsedSeconds =
    (readingNumber - 1) * LOG_INTERVAL_SECONDS;

  file.print(readingNumber);
  file.print(",");
  file.print(elapsedSeconds);
  file.print(",");
  file.print(adcValue);
  file.print(",");
  file.println(voltage, 3);

  file.close();

  Serial.print("Reading ");
  Serial.print(readingNumber);
  Serial.print("  ADC=");
  Serial.print(adcValue);
  Serial.print("  Voltage=");
  Serial.print(voltage, 3);
  Serial.println(" V");
}
